import java.lang.annotation.ElementType;
import java.lang.annotation.Target;

@Target(ElementType.METHOD)
@interface Action {
    String value();
}

enum Status { READY, RUNNING, FINISHED }

final class Controller {
    private Status status = Status.READY;

    @Action("refresh")
    public void refresh() {
        status = Status.RUNNING;
    }
}

import java.util.List;
import java.util.concurrent.CompletableFuture;

final class AsyncTasks {
    CompletableFuture<List<String>> load(List<String> paths) {
        return CompletableFuture.supplyAsync(() -> paths.stream()
            .filter(path -> !path.isBlank())
            .map(String::strip)
            .sorted()
            .toList());
    }
}

package demo;

import java.util.List;

public final class Hello {
    private final String greeting;

    public Hello(String greeting) {
        this.greeting = greeting;
    }

    public void welcome(List<String> names) {
        for (String name : names) {
            System.out.println(greeting + ", " + name);
        }
    }

    public static void main(String[] args) {
        var app = new Hello("Hello");
        app.welcome(List.of("Virgo", "世界 🌍"));
    }
}

sealed interface Message permits Notice, Progress {}
record Notice(String text) implements Message {}
record Progress(int completed, int total) implements Message {}

final class Router {
    String describe(Message message) {
        return switch (message) {
            case Notice(var text) when !text.isBlank() -> text;
            case Progress(var done, var total) -> "%d / %d".formatted(done, total);
            default -> "Waiting";
        };
    }
}

import java.util.Objects;
import java.util.function.Function;

public record Result<T>(T value, String label) {
    public Result {
        label = Objects.requireNonNull(label).strip();
    }

    public <R> Result<R> map(Function<T, R> transform) {
        return new Result<>(transform.apply(value), label);
    }
}

final class TextTemplates {
    String render(String title) {
        String template = """
            <article class="code-card">
                <h2>%s</h2>
                <!-- Preserve this as string content. -->
            </article>
            """;
        return template.formatted(title);
    }
}

